package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneDuplicateException;

/**
 * Runs after {@link ValidateOwner} (which has converted the telephone to E.164 and republished the
 * body) and before {@link BuildOwner}. Rejects the create with a 409 via
 * {@link OwnerTelephoneDuplicateException} when the E.164 telephone already belongs to any other
 * owner. Existing owners are compared on their telephone converted to E.164 the same way, so stored
 * values with incidental formatting still match.
 */
public class CheckOwnerTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerTelephoneDuplicateException {
        // ValidateOwner has already converted the request telephone to E.164; only stored owners need it.
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(OwnerTelephone.toE164(existing.getTelephone()))) {
                throw new OwnerTelephoneDuplicateException(telephone);
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.CheckOwnerTelephoneUnique}
 * when the normalized owner telephone being created already belongs to another owner. Handled by
 * {@link OwnerTelephoneDuplicateExceptionHandler}, which responds 409.
 */
public class OwnerTelephoneDuplicateException extends Exception {

    private final String telephone;

    public OwnerTelephoneDuplicateException(String telephone) {
        super("Telephone already in use by another owner: " + telephone);
        this.telephone = telephone;
    }

    public String getTelephone() {
        return this.telephone;
    }
}
package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;
import java.util.Map;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

/**
 * Responds 409 with a JSON body whose {@code errors} array names {@code telephone} when the
 * normalized telephone being created is already used by another owner.
 */
public class OwnerTelephoneDuplicateExceptionHandler {

    public void handle(@Parameter OwnerTelephoneDuplicateException ex,
            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
        Map<String, Object> body = Map.of("errors", List.of("telephone"));
        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(body));
    }
}

